// src/services/api.js
// Centralized API service. All fetch calls go through here.
// The "proxy" field in package.json forwards /api/* to http://localhost:8080
// so no hardcoded base URL is needed during development.

const BASE = '/api/requests';

async function request(url, options = {}) {
  const res = await fetch(url, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) {
    throw new Error(data?.error || `Request failed: ${res.status}`);
  }
  return data;
}

export const api = {
  // FR-3: list all / FR-11-14: search & filter
  getRequests(params = {}) {
    const query = new URLSearchParams();
    if (params.status)    query.set('status', params.status);
    if (params.priority)  query.set('priority', params.priority);
    if (params.requester) query.set('requester', params.requester);
    if (params.keyword)   query.set('keyword', params.keyword);
    const qs = query.toString();
    return request(`${BASE}${qs ? '?' + qs : ''}`);
  },

  // FR-4: view single request
  getRequest(id) {
    return request(`${BASE}/${id}`);
  },

  // FR-1: create request
  createRequest(body) {
    return request(BASE, { method: 'POST', body: JSON.stringify(body) });
  },

  // FR-6: update status / FR-7+8: update priority
  updateRequest(id, body) {
    return request(`${BASE}/${id}`, { method: 'PATCH', body: JSON.stringify(body) });
  },
};
